import { useState } from "react";
import {
  Avatar,
  Box,
  Card,
  CardContent,
  Container,
  Grid,
  IconButton,
  Stack,
  Typography,
} from "@mui/material";
import masterData from "../../data/masterData.json";
import {
  ChevronLeftIcon,
  ChevronRightIcon,
  FormatQuoteIcon,
} from "../../utils/iconMap";

export default function TestimonialsSection() {
  const { testimonials, sections } = masterData;
  const [start, setStart] = useState(0);
  const visibleCount = 3;

  const prev = () => {
    setStart((s) => (s - 1 + testimonials.length) % testimonials.length);
  };

  const next = () => {
    setStart((s) => (s + 1) % testimonials.length);
  };

  const visible = Array.from(
    { length: Math.min(visibleCount, testimonials.length) },
    (_, i) => testimonials[(start + i) % testimonials.length]
  );

  return (
    <Box sx={{ py: { xs: 6, md: 8 }, bgcolor: "#F7FAFF" }}>
      <Container maxWidth="lg">
        <Stack
          direction="row"
          justifyContent="space-between"
          alignItems="center"
          sx={{ mb: 3.5 }}
        >
          <Typography
            sx={{ fontWeight: 800, color: "#0B1F3A", fontSize: { xs: "1.35rem", md: "1.85rem" } }}
          >
            {sections.testimonials.title}
          </Typography>
          <Stack direction="row" spacing={1}>
            <IconButton
              onClick={prev}
              sx={{
                border: "1px solid #D7E0EC",
                bgcolor: "#fff",
                width: 36,
                height: 36,
                "&:hover": { bgcolor: "#EEF4FC" },
              }}
              aria-label="Previous"
            >
              <ChevronLeftIcon sx={{ fontSize: 20 }} />
            </IconButton>
            <IconButton
              onClick={next}
              sx={{
                border: "1px solid #D7E0EC",
                bgcolor: "#fff",
                width: 36,
                height: 36,
                "&:hover": { bgcolor: "#EEF4FC" },
              }}
              aria-label="Next"
            >
              <ChevronRightIcon sx={{ fontSize: 20 }} />
            </IconButton>
          </Stack>
        </Stack>

        <Grid container spacing={2.5}>
          {visible.map((item) => (
            <Grid key={`${item.id}-${start}`} size={{ xs: 12, md: 4 }}>
              <Card
                elevation={0}
                sx={{
                  height: "100%",
                  borderRadius: "14px",
                  border: "1px solid #E8EEF5",
                  bgcolor: "#fff",
                  boxShadow: "0 4px 18px rgba(15, 40, 80, 0.04)",
                }}
              >
                <CardContent sx={{ p: 3, "&:last-child": { pb: 3 } }}>
                  <Stack direction="row" spacing={2} alignItems="flex-start">
                    <Avatar
                      src={item.avatar}
                      alt={item.name}
                      sx={{ width: 52, height: 52, flexShrink: 0 }}
                    />
                    <Box sx={{ flex: 1, minWidth: 0 }}>
                      <FormatQuoteIcon
                        sx={{ color: "#0056D2", fontSize: 22, opacity: 0.45, mb: 0.25 }}
                      />
                      <Typography
                        sx={{
                          color: "#0056D2",
                          fontWeight: 500,
                          fontSize: 14,
                          lineHeight: 1.55,
                          mb: 1.5,
                          fontStyle: "italic",
                        }}
                      >
                        {item.quote}
                      </Typography>
                      <Typography sx={{ fontWeight: 700, color: "#0B1F3A", fontSize: 13.5 }}>
                        {item.name}
                      </Typography>
                      <Typography sx={{ fontSize: 12, color: "#6B7C93" }}>{item.role}</Typography>
                    </Box>
                  </Stack>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>
      </Container>
    </Box>
  );
}
